```python
#!/usr/bin/env python3
"""stress_judge.py - judge a nand-stress UART log (nand-stress 2.x text format or 3.0 JSON Lines).

Used by the CI job `nand-stress` after the board finishes. Rules follow
SV-TS-014 rev C section 5 (NAND stress pass/fail criteria).

Usage:
    stress_judge.py LOGFILE

Output (stdout):
    SUMMARY: key=value ...              （內容不限，供人看）
    VERDICT: PASS                      exit 0
    VERDICT: FAIL CODE[,CODE...]       exit 1   (codes in the order of RULES)
    VERDICT: ERROR <原因>              exit 2   (not a nand-stress log)
"""
import re
import json
import sys

RULES = ["VERIFY", "UECC", "BB_GROWTH", "BITFLIP_HIGH", "INCOMPLETE", "KERNEL_OOPS"]

BB_GROWTH_LIMIT = 4        # new bad blocks allowed during one run (> 4 fails)
HIGH_BITFLIP_LIMIT = 10    # iterations with max bitflips >= 7 allowed (> 10 fails)

# Regex for v1 log format
TS = r"^\[(\d{4}-\d\d-\d\d \d\d:\d\d:\d\d)\]\s+"
RE_START = re.compile(TS + r"nand-stress (\S+) start .*?target_iter=(\d+)")
RE_BB_TOTAL = re.compile(TS + r"bbt: total bad blocks (\d+)")
RE_BB_NEW = re.compile(TS + r"bbt: new bad block (\d+)")
RE_PROGRESS = re.compile(TS + r"progress iter (\d+)/(\d+)")
RE_HIGHBF = re.compile(TS + r"ecc: high bitflips iter (\d+) peb (\d+) max (\d+)")
RE_UECC = re.compile(TS + r"ecc: uncorrectable iter (\d+) peb (\d+)")
RE_VERIFY = re.compile(TS + r"verify: mismatch iter (\d+) peb (\d+)")
RE_END = re.compile(TS + r"nand-stress end iter=(\d+)/(\d+)")
RE_OOPS = re.compile(r"Oops|Kernel panic|BUG:|Unable to handle kernel")

# Regex for v2 JSON Lines format
RE_JSON_EVENT = re.compile(r'^\{.*\}$')

class Run:
    def __init__(self):
        self.version = None
        self.target = None
        self.bb_initial = None
        self.bb_final = None
        self.bb_new = []
        self.last_iter = 0
        self.ended = False
        self.high_bitflip_iters = set()
        self.uecc = []
        self.verify = []
        self.oops = []


def parse_v1(lines):
    run = Run()
    for raw in lines:
        line = raw.rstrip("\r\n")
        if not line.strip():
            continue

        m = RE_START.match(line)
        if m:
            run.version = m.group(2)
            run.target = int(m.group(3))
            continue

        m = RE_BB_TOTAL.match(line)
        if m:
            n = int(m.group(2))
            if not run.bb_initial:
                run.bb_initial = n
            run.bb_final = n
            continue

        m = RE_BB_NEW.match(line)
        if m:
            run.bb_new.append(int(m.group(2)))
            continue

        m = RE_PROGRESS.match(line)
        if m:
            run.last_iter = max(run.last_iter, int(m.group(2)))
            continue

        m = RE_HIGHBF.match(line)
        if m:
            if int(m.group(4)) >= 7:
                run.high_bitflip_iters.add(int(m.group(2)))
            continue

        m = RE_UECC.match(line)
        if m:
            run.uecc.append((int(m.group(2)), int(m.group(3))))
            continue

        m = RE_VERIFY.match(line)
        if m:
            run.verify.append((int(m.group(2)), int(m.group(3))))
            continue

        m = RE_END.match(line)
        if m:
            run.ended = True
            run.last_iter = max(run.last_iter, int(m.group(2)))
            continue

        # kernel messages are forwarded with a "kernel:" tag; oops can also
        # appear without the tag when the console is shared
        if RE_OOPS.search(line):
            run.oops.append(line)
    return run


def parse_v2(lines):
    run = Run()
    for line in lines:
        line = line.rstrip("\r\n")
        if not line.strip():
            continue

        try:
            data = json.loads(line)
        except json.JSONDecodeError:
            continue  # Skip malformed JSON

        if data.get("ev") == "start":
            run.version = data.get("ver")
            run.target = int(data.get("target_iter"))
        elif data.get("ev") == "bbt":
            if data.get("total") is not None:
                if not run.bb_initial:
                    run.bb_initial = int(data.get("total"))
                run.bb_final = int(data.get("total"))
            elif data.get("new") is not None:
                run.bb_new.append(int(data.get("new")))
        elif data.get("ev") == "iter":
            iter_n = int(data.get("n"))
            if iter_n >= 0:
                run.last_iter = max(run.last_iter, iter_n)
            if data.get("max_bitflips") is not None and int(data.get("max_bitflips")) >= 7:
                run.high_bitflip_iters.add(iter_n)
        elif data.get("ev") == "ecc":
            if data.get("kind") == "uncorrectable":
                run.uecc.append((int(data.get("iter")), int(data.get("peb"))))
        elif data.get("ev") == "kmsg":
            if RE_OOPS.search(data.get("text", "")):
                run.oops.append(data.get("text"))
        elif data.get("ev") == "end":
            run.ended = True
            run.last_iter = max(run.last_iter, int(data.get("iter")))
    return run


def parse(lines):
    # First check if the log starts with a JSON event
    if RE_JSON_EVENT.match(lines[0]):
        # Try parsing as v2 JSON Lines
        try:
            return parse_v2(lines)
        except Exception as e:
            print(f"VERDICT: ERROR cannot parse JSON log: {e}")
            return None
    else:
        # Try parsing as v1 text format
        try:
            return parse_v1(lines)
        except Exception as e:
            print(f"VERDICT: ERROR cannot parse text log: {e}")
            return None


def judge(run):
    fails = []
    if run.verify:
        fails.append("VERIFY")
    if run.uecc:
        fails.append("UECC")
    growth = 0
    if run.bb_initial is not None and run.bb_final is not None:
        growth = run.bb_final - run.bb_initial
    if growth > BB_GROWTH_LIMIT:
        fails.append("BB_GROWTH")
    if len(run.high_bitflip_iters) > HIGH_BITFLIP_LIMIT:
        fails.append("BITFLIP_HIGH")
    if not run.ended or run.last_iter < run.target:
        fails.append("INCOMPLETE")
    if run.oops:
        fails.append("KERNEL_OOPS")
    return fails, growth


def main(argv):
    if len(argv) != 2:
        print(__doc__.strip().splitlines()[0])
        print("usage: stress_judge.py LOGFILE")
        return 2
    try:
        with open(argv[1], encoding="utf-8", errors="replace") as f:
            lines = f.readlines()
    except OSError as e:
        print(f"VERDICT: ERROR cannot read log: {e}")
        return 2

    run = parse(lines)
    if run is None or run.target is None:
        print("VERDICT: ERROR no nand-stress start line")
        return 2

    fails, growth = judge(run)
    print(f"SUMMARY: version={run.version} target={run.target} last_iter={run.last_iter} "
          f"ended={int(run.ended)} bb_initial={run.bb_initial} bb_final={run.bb_final} "
          f"bb_growth={growth} high_bitflip_iters={len(run.high_bitflip_iters)} "
          f"uecc={len(run.uecc)} verify={len(run.verify)} oops={len(run.oops)}")
    if fails:
        print("VERDICT: FAIL " + ",".join(r for r in RULES if r in fails))
        return 1
    print("VERDICT: PASS")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
```

## NCR-0611 問題分析

### 1. 問題現象

從 NCR-0611 的 MAC 重複表看出：
- CF9G-07-0001 (index=0) 與 CF9G-07-0129 (index=128) 的 MAC 完全相同
- CF9G-07-0002 (index=1) 與 CF9G-07-0130 (index=129) 的 MAC 完全相同
- 依此類推，共 12 組重複

### 2. 根本原因

查看 `tools/fct/fct_tool.c` 的 `mac_add()` 函數：

```c
static int mac_add(u8 mac[6], u32 n)
{
    u32 carry = n;
    int i;

    for (i = 5; i >= OUI_LEN && carry; i--) {
        u8 v = mac[i] + carry;
        mac[i] = v & 0xff;
        carry = v >> 8;
    }
    return carry ? -ERANGE : 0;
}
```

**問題**：迴圈條件 `i >= OUI_LEN` 中 `OUI_LEN` 定義為 3，但 `i` 從 5 開始，當 `i=3` 時會進入迴圈。此處邏輯錯誤：
- MAC 位元組：`mac[0..2]` = OUI（不可動）
- MAC 位元組：`mac[3..5]` = NIC part（可加）
- 迴圈應該在 `i >= OUI_LEN` 時**停止**，但條件寫成 `i >= OUI_LEN` 會**包含** `i=3`

正確邏輯應為 `i > OUI_LEN` 或 `i >= OUI_LEN + 1`，這樣 `i=3` 時就不會進迴圈。

### 3. 問題驗證

以 `02:CF:06:3C:12:00` 加 256（index=128, 2×128=256）：
- 正確結果：`02:CF:06:3C:13:00`（NIC part 從 `12:00` = 0x1200 加 0x100）
- 實際結果：`02:CF:06:3C:12:00`（因為 `mac[3]` 被錯誤修改，carry 沒有正確傳播到 `mac[2]`）

當 NIC part 超過 `00:FF:FF` 時，carry 沒有回傳到 OUI，導致 MAC 重複。

### 4. 修正 Patch

```diff
--- a/tools/fct/fct_tool.c
+++ b/tools/fct/fct_tool.c
@@ -104,7 +104,7 @@ static int mac_add(u8 mac[6], u32 n)
 {
 	u32 carry = n;
 	int i;
-
+
 	for (i = 5; i >= OUI_LEN && carry; i--) {
 		u8 v = mac[i] + carry;

@@ -112,6 +112,8 @@ static int mac_add(u8 mac[6], u32 n)
 		carry = v >> 8;
 	}
 	return carry ? -ERANGE : 0;
+
+	/* OUI (bytes 0..2) is never touched; overflow past FF:FF:FF is an error. */
 }
```

**修正說明**：
1. 將迴圈條件從 `i >= OUI_LEN` 改為 `i > OUI_LEN`（或 `i >= 4`）
2. 這樣 `mac[3]` 是 NIC part 的最低位元組，`mac[3]` 仍可被修改，但 `mac[2]` 不會被觸及
3. 當 NIC part 超過 `00:FF:FF` 時，`mac_add()` 會回傳 `-ERANGE`，`mac_for_unit()` 會回傳錯誤，`mac-alloc` 會輸出 `FCT MAC_ALLOC FAIL pool exhausted`

**正確 patched 版本**：

